const response=await fetch('profile-data.json');if(!response.ok)throw new Error('Profile unavailable');const data=await response.json();
const list=document.querySelector('#career-history');
for(const role of data.roles){const article=document.createElement('article');article.className='career-row';const date=document.createElement('p');date.className='career-date';date.textContent=role.period;const details=document.createElement('details'),summary=document.createElement('summary'),h=document.createElement('h2');h.textContent=role.company;const title=document.createElement('p');title.className='career-role';title.append(document.createTextNode(role.title));const pill=document.createElement('span');pill.className='career-pill';pill.textContent=role.engagement;title.append(pill);const intro=document.createElement('p');intro.className='career-summary';intro.textContent=role.summary;summary.append(h,title,intro);const ul=document.createElement('ul');for(const text of role.highlights){const li=document.createElement('li');li.textContent=text;ul.append(li)}const tags=document.createElement('div');tags.className='career-tags';for(const text of role.technologies){const span=document.createElement('span');span.textContent=text;tags.append(span)}details.append(summary,ul,tags);article.append(date,details);list.append(article)}
